```shell
curl http://localhost:11434/api/embed -d '{
 "model": "embeddinggemma2",
 "input": [
 "a plain text query",
 {"image": "iVBORw0KGgo..."},
 {"audio": "UklGRiQAAABXQVZF..."}
 ]
}'
```
